<?php declare(strict_types=1);function th(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function tm(mixed $v):string{return number_format((float)$v,0,',',' ').' FCFA';}$canSign=(bool)($user['valider_devis']??false)||(bool)($user['gestion_utilisateur']??false);?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trésorerie & décaissements · FIDEST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/modules.css"><style>
.tr-shell{max-width:1450px}.tr-hero{padding:27px;margin-bottom:18px;color:#fff;background:linear-gradient(125deg,var(--brand-primary),#414578);border-radius:22px}.tr-hero h1{margin:0;color:#fff!important}.tr-hero p{margin:6px 0 0;color:#ffffffb5}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin-bottom:18px}.kpi,.panel{background:#fff;border:1px solid var(--brand-border);border-radius:18px;box-shadow:0 9px 28px #22254b0c}.kpi{padding:18px}.kpi small{display:block;color:#777a8d;font-weight:800;text-transform:uppercase}.kpi strong{display:block;margin-top:8px;color:var(--brand-primary);font-size:1.35rem}.kpi.forecast strong{color:#5b4bb7}.panel{padding:20px;margin-bottom:18px}.panel h2{margin:0 0 5px;color:var(--brand-primary);font-size:1.08rem}.panel-note{color:#74778a;font-size:.78rem}.plan-grid{display:grid;grid-template-columns:1.1fr .65fr .8fr .8fr 1fr auto;gap:8px;align-items:end;padding:13px 0;border-top:1px solid #ececf2}.feb-label small{display:block;color:#777a8d}.table{font-size:.78rem}.status{font-size:.64rem;text-transform:uppercase}.source-invoice{display:none}.source-invoice.active{display:block}@media(max-width:1050px){.kpis{grid-template-columns:1fr 1fr}.plan-grid{grid-template-columns:1fr 1fr}.plan-grid .feb-label{grid-column:1/-1}}@media(max-width:560px){.kpis{grid-template-columns:1fr}.plan-grid{grid-template-columns:1fr}}
</style></head><body class="module-page"><?php include APP_ROOT.'/partials/navbar.php';?><main class="container tr-shell"><header class="tr-hero"><h1><i class="fa-solid fa-vault me-2 text-warning"></i>Trésorerie & planification des décaissements</h1><p>Couverture des FEB, arrêté du point du jour, visa DG et exécution contrôlée.</p></header><?php if($flash):?><div class="alert alert-<?=th($flash['type'])?>"><?=th($flash['message'])?></div><?php endif;?><section class="kpis"><article class="kpi"><small>Solde réel disponible</small><strong><?=tm($summary['real_balance'])?></strong><span class="panel-note">Solde initial + encaissements − décaissements</span></article><article class="kpi"><small>Entrées réelles</small><strong class="text-success"><?=tm($summary['real_in'])?></strong></article><article class="kpi forecast"><small>Encaissements prévisionnels</small><strong><?=tm($summary['forecast_in'])?></strong><span class="panel-note">Reliquat des factures émises</span></article><article class="kpi forecast"><small>Solde prévisionnel net</small><strong><?=tm($summary['forecast_balance'])?></strong><span class="panel-note">Après FEB planifiées</span></article></section>
<section class="panel"><div class="d-flex flex-wrap justify-content-between gap-3"><div><h2>Référence du solde réel</h2><div class="panel-note">Point de départ comptable utilisé avant les encaissements et décaissements enregistrés.</div></div><form method="post" action="request/treasury_action.php" class="d-flex gap-2 align-items-end"><input type="hidden" name="csrf" value="<?=th($csrf)?>"><input type="hidden" name="action" value="opening"><label class="form-label small mb-0">Date<input class="form-control form-control-sm" type="date" name="date" required value="<?=th($summary['opening']['opening_date'])?>"></label><label class="form-label small mb-0">Solde initial<input class="form-control form-control-sm" type="number" step="0.01" name="amount" required value="<?=th($summary['opening']['opening_balance'])?>"></label><button class="btn btn-sm btn-outline-primary">Actualiser</button></form></div></section>
<section class="panel"><h2>FEB approuvées à couvrir et planifier</h2><p class="panel-note">Une réservation ne débite pas le solde réel. Elle devient un décaissement uniquement après arrêté, visa DG et exécution.</p><?php foreach($febs as $feb):?><form class="plan-grid funding-form" method="post" action="request/treasury_action.php"><input type="hidden" name="csrf" value="<?=th($csrf)?>"><input type="hidden" name="action" value="plan"><input type="hidden" name="feb_id" value="<?=(int)$feb['id']?>"><div class="feb-label"><strong><?=th($feb['numero_feb'])?> · <?=tm($feb['montant_demande'])?></strong><small><?=th($feb['nom_client'])?> · <?=th($feb['numero_bc'])?><?=!empty($feb['plan_status'])?' · déjà planifiée':''?></small></div><label class="small">Source<select class="form-select form-select-sm funding-source" name="source_type"><option value="real" <?=$feb['source_type']==='real'?'selected':''?>>Solde réel</option><option value="forecast" <?=$feb['source_type']==='forecast'?'selected':''?>>Facture prévisionnelle</option></select></label><label class="small source-invoice <?=$feb['source_type']==='forecast'?'active':''?>">Facture<select class="form-select form-select-sm" name="invoice_id"><option value="">Choisir…</option><?php foreach($invoices as $invoice):?><option value="<?=(int)$invoice['id']?>" <?=$feb['invoice_id']==$invoice['id']?'selected':''?>><?=th($invoice['numero_facture'].' · '.$invoice['nom_client'].' · '.tm($invoice['remaining']))?></option><?php endforeach;?></select></label><label class="small">Date précise<input class="form-control form-control-sm" type="date" name="scheduled_date" required value="<?=th($feb['scheduled_date']?:$feb['date_disponibilite'])?>"></label><input type="hidden" name="amount" value="<?=th($feb['montant_demande'])?>"><label class="small">Note<input class="form-control form-control-sm" name="note" value="<?=th($feb['note'])?>" placeholder="Objet / instruction"></label><button class="btn btn-sm btn-primary"><i class="fa-solid fa-calendar-check"></i> Planifier</button></form><?php endforeach;?><?php if(!$febs):?><div class="text-center text-muted py-4">Aucune FEB approuvée en attente de décaissement.</div><?php endif;?></section>
<section class="panel"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3"><div><h2>Arrêter le point du jour</h2><p class="panel-note mb-0">L’arrêté fige toutes les FEB planifiées à la date choisie.</p></div><form method="post" action="request/treasury_action.php" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=th($csrf)?>"><input type="hidden" name="action" value="close"><input class="form-control" type="date" name="point_date" max="<?=date('Y-m-d')?>" value="<?=date('Y-m-d')?>" required><button class="btn btn-warning text-nowrap"><i class="fa-solid fa-lock"></i> Arrêter le point</button></form></div></section>
<section class="panel"><h2>Points des décaissements</h2><p class="panel-note">Registre horodaté des arrêtés, signatures et décaissements.</p><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Point</th><th>Date</th><th>Lignes</th><th>Total</th><th>Traçabilité</th><th>Statut</th><th>Actions</th></tr></thead><tbody><?php foreach($points as $p):?><tr><td><strong><?=th($p['point_number'])?></strong><small class="d-block text-muted"><?=th($p['document_uid'])?></small></td><td><?=date('d/m/Y',strtotime($p['point_date']))?></td><td><?=(int)$p['line_count']?></td><td><strong><?=tm($p['total_amount'])?></strong></td><td><small>Arrêté : <?=th($p['closed_name'])?><br>DG : <?=th($p['signed_name']?:'—')?><br>Décaissé : <?=th($p['executed_name']?:'—')?></small></td><td><span class="badge status text-bg-<?=$p['status']==='executed'?'success':($p['status']==='signed'?'primary':'warning')?>"><?=th($p['status'])?></span></td><td><div class="d-flex flex-wrap gap-1"><a target="_blank" class="btn btn-sm btn-outline-danger" href="request/export_disbursement_point_pdf.php?id=<?=(int)$p['id']?>"><i class="fa-solid fa-file-pdf"></i></a><a class="btn btn-sm btn-outline-success" href="request/export_disbursement_point_excel.php?id=<?=(int)$p['id']?>"><i class="fa-solid fa-file-excel"></i></a><?php if($p['status']==='closed'&&$canSign):?><form method="post" action="request/treasury_action.php"><input type="hidden" name="csrf" value="<?=th($csrf)?>"><input type="hidden" name="action" value="sign"><input type="hidden" name="point_id" value="<?=(int)$p['id']?>"><button class="btn btn-sm btn-primary" onclick="return confirm('Signer définitivement ce point du jour ?')">Visa DG</button></form><?php elseif($p['status']==='signed'):?><form method="post" action="request/treasury_action.php" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=th($csrf)?>"><input type="hidden" name="action" value="execute"><input type="hidden" name="point_id" value="<?=(int)$p['id']?>"><input class="form-control form-control-sm" name="payment_reference" required placeholder="Référence paiement"><button class="btn btn-sm btn-success" onclick="return confirm('Confirmer le décaissement effectif de toutes les lignes ?')">Décaisser</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php if(!$points):?><div class="text-center text-muted py-4">Aucun point journalier arrêté.</div><?php endif;?></section></main><script>document.querySelectorAll('.funding-source').forEach(select=>{const sync=()=>select.closest('form').querySelector('.source-invoice').classList.toggle('active',select.value==='forecast');select.addEventListener('change',sync);sync()})</script></body></html>
